package com.resolver.dns

import java.util.concurrent.{ConcurrentHashMap, Executors, TimeUnit}
import java.util.concurrent.atomic.{AtomicReference, AtomicInteger}
import java.util.concurrent.locks.ReentrantReadWriteLock
import scala.collection.mutable
import scala.concurrent.{ExecutionContext, Future, Promise}
import scala.util.{Try, Success, Failure}

case class DnsRecord(host: String, ip: String, ttl: Long, timestamp: Long)
case class ResolverConfig(maxCacheSize: Int, ttlOverride: Option[Long], trustedServers: List[String])

class DnsCache(config: ResolverConfig) {
  private val cache = new ConcurrentHashMap[String, DnsRecord]()
  private val pendingResolutions = new ConcurrentHashMap[String, Promise[DnsRecord]]()
  private val configRef = new AtomicReference[ResolverConfig](config)
  private val configLock = new ReentrantReadWriteLock()
  private val resolutionCount = new AtomicInteger(0)

  def updateConfig(newConfig: ResolverConfig): Unit = {
    configLock.writeLock().lock()
    try {
      configRef.set(newConfig)
    } finally {
      configLock.writeLock().unlock()
    }
  }

  def withConfig[T](f: ResolverConfig => T): T = {
    configLock.readLock().lock()
    try {
      f(configRef.get())
    } finally {
      configLock.readLock().unlock()
    }
  }

  def getCached(host: String): Option[DnsRecord] = {
    Option(cache.get(host)).filter(isValid)
  }

  private def isValid(record: DnsRecord): Boolean = {
    val now = System.currentTimeMillis()
    withConfig { cfg =>
      val effectiveTtl = cfg.ttlOverride.getOrElse(record.ttl)
      (now - record.timestamp) < effectiveTtl * 1000
    }
  }

  def putRecord(record: DnsRecord): Unit = {
    withConfig { cfg =>
      if (cache.size() < cfg.maxCacheSize) {
        cache.put(record.host, record)
      }
    }
  }

  def getPending(host: String): Option[Promise[DnsRecord]] = {
    Option(pendingResolutions.get(host))
  }

  def setPending(host: String, promise: Promise[DnsRecord]): Option[Promise[DnsRecord]] = {
    Option(pendingResolutions.putIfAbsent(host, promise))
  }

  def removePending(host: String): Unit = {
    pendingResolutions.remove(host)
  }

  def incrementAndGetCount(): Int = resolutionCount.incrementAndGet()
}

class DnsResolver(envPrefix: String = "DNS_RESOLVER") {
  private val executor = Executors.newFixedThreadPool(4)
  implicit val ec: ExecutionContext = ExecutionContext.fromExecutor(executor)

  private val cache: DnsCache = {
    val maxCache = sys.env.getOrElse(s"${envPrefix}_MAX_CACHE", "1000").toInt
    val ttlOverride = sys.env.get(s"${envPrefix}_TTL_OVERRIDE").map(_.toLong)
    val trusted = sys.env.getOrElse(s"${envPrefix}_TRUSTED_SERVERS", "8.8.8.8,8.8.4.4")
      .split(",").toList
    new DnsCache(ResolverConfig(maxCache, ttlOverride, trusted))
  }

  def resolve(host: String): Future[DnsRecord] = {
    cache.getCached(host) match {
      case Some(record) => Future.successful(record)
      case None => resolveWithDedup(host)
    }
  }

  private def resolveWithDedup(host: String): Future[DnsRecord] = {
    val promise = Promise[DnsRecord]()
    cache.setPending(host, promise) match {
      case Some(existing) => existing.future
      case None =>
        performResolution(host).onComplete { result =>
          result match {
            case Success(record) =>
              cache.putRecord(record)
              promise.success(record)
            case Failure(ex) =>
              promise.failure(ex)
          }
          cache.removePending(host)
        }
        promise.future
    }
  }

  private def performResolution(host: String): Future[DnsRecord] = Future {
    cache.withConfig { config =>
      val server = selectServer(config, host)
      val result = queryDnsServer(server, host)
      validateAndBuild(host, result, config)
    }
  }

  private def selectServer(config: ResolverConfig, host: String): String = {
    val count = cache.incrementAndGetCount()
    val serverList = config.trustedServers
    serverList(count % serverList.size)
  }

  private def queryDnsServer(server: String, host: String): String = {
    // Simulated DNS query - in production this would be a UDP/TCP call
    Thread.sleep(50)
    s"192.168.1.${Math.abs(host.hashCode % 254) + 1}"
  }

  private def validateAndBuild(host: String, ip: String, config: ResolverConfig): DnsRecord = {
    val ttl = config.ttlOverride.getOrElse(300L)
    DnsRecord(host, ip, ttl, System.currentTimeMillis())
  }

  def reloadConfig(): Unit = {
    val maxCache = sys.env.getOrElse(s"${envPrefix}_MAX_CACHE", "1000").toInt
    val ttlOverride = sys.env.get(s"${envPrefix}_TTL_OVERRIDE").map(_.toLong)
    val trusted = sys.env.getOrElse(s"${envPrefix}_TRUSTED_SERVERS", "8.8.8.8,8.8.4.4")
      .split(",").toList
    cache.updateConfig(ResolverConfig(maxCache, ttlOverride, trusted))
  }

  def shutdown(): Unit = {
    executor.shutdown()
    executor.awaitTermination(5, TimeUnit.SECONDS)
  }
}

object DnsResolverApp extends App {
  val resolver = new DnsResolver()

  val hosts = List("example.com", "api.service.internal", "db.cluster.local")

  implicit val ec: ExecutionContext = ExecutionContext.global

  val futures = hosts.map { host =>
    resolver.resolve(host).map { record =>
      println(s"Resolved ${record.host} -> ${record.ip} (TTL: ${record.ttl}s)")
      record
    }
  }

  Future.sequence(futures).onComplete { _ =>
    resolver.shutdown()
  }

  Thread.sleep(3000)
}
